let selectedAge="primary", currentTopic=topics[0], chosenAnswer=null, questionResolved=false, questionIndex=0, activeQuestions=[];
const $=id=>document.getElementById(id);

function showScreen(name){
 document.querySelectorAll(".screen").forEach(s=>s.classList.remove("active"));
 const target=$("screen-"+name); if(target) target.classList.add("active");
 window.scrollTo({top:0,behavior:"smooth"});
}
const completedTopics = new Set();
function renderTopics(){
 $("topicsWelcome").textContent=selectedAge==="primary"?"أهلًا يا أبطال! جاهزين نكتشف؟":"أهلًا بيكم! جاهزين نفكر ونناقش؟";
 $("topicGrid").innerHTML="";
 topics.forEach(topic=>{
  const button=document.createElement("button");
  button.className="topic-card";
  button.innerHTML=`<span class="topic-num">${String(topic.id).padStart(2,"0")}</span><span><strong>${topic.title}</strong><small>${topic.desc}</small></span><span class="status">${completedTopics.has(topic.id)?"تم":"ابدأ"}</span>`;
  button.addEventListener("click",()=>openTopic(topic));
  $("topicGrid").appendChild(button);
 });
}
function openTopic(topic){
 currentTopic=topic;
 $("topicNumber").textContent=`الموضوع ${String(topic.id).padStart(2,"0")}`;
 $("topicTitle").textContent=topic.title; $("topicIntro").textContent=topic.intro;
 $("topicGoal").textContent=topic.goal; $("topicSymbol").textContent=topic.symbol;
 const objectiveBox=$("topicObjectives");
 if(objectiveBox) objectiveBox.innerHTML="<strong>بعد الموضوع هنكون قادرين على:</strong><ul>"+topic.objectives.map(x=>`<li>${x}</li>`).join("")+"</ul>";
 showScreen("topic-intro");
}
function expandableNotes(notes, label="نقاط تساعدك في الشرح", id=""){
 return `<div class="presenter-extra hidden" ${id?`id="${id}"`:""}><strong>${label}</strong><ul>${notes.map(n=>`<li>${n}</li>`).join("")}</ul></div>`;
}
function bindExpandButtons(root=document){
 root.querySelectorAll("[data-expand]").forEach(button=>{
  if(button.dataset.bound==="yes") return;
  button.dataset.bound="yes";
  button.addEventListener("click",()=>{
   const panel=$(button.dataset.expand);
   if(!panel)return;
   const open=button.getAttribute("aria-expanded")==="true";
   button.setAttribute("aria-expanded",String(!open));
   button.textContent=open?"＋":"−";
   panel.classList.toggle("hidden",open);
  });
 });
}
function startStory(){
 const story=currentTopic.story;
 const variant=selectedAge==="primary"?story.primary:story.older;
 $("storyTitle").textContent=story.title;
 $("storyText").textContent=variant.text;
 $("storyPrompt").innerHTML=`<div class="story-prompt-text">${variant.prompt}</div>
  <button class="presenter-expand story-expand" type="button" data-expand="storyPresenterNotesPanel" aria-expanded="false" aria-label="إظهار نقاط الإجابة">＋</button>
  ${expandableNotes(variant.notes,"أفكار وإجابات متوقعة للموقف","storyPresenterNotesPanel")}`;
 bindExpandButtons($("storyPrompt"));
 $("discussionList").innerHTML=currentTopic.discussion.map((item,i)=>`
  <article class="discussion-item">
   <div class="discussion-main"><span>${String(i+1).padStart(2,"0")}</span><p>${item.q}</p></div>
   <button class="notes-toggle" type="button" data-expand="discussionNotes${i}" aria-expanded="false" aria-label="إظهار شرح السؤال">＋</button>
   <div class="presenter-notes hidden" id="discussionNotes${i}"><strong>نقاط تساعدك في الشرح</strong><ul>${item.notes.map(n=>`<li>${n}</li>`).join("")}</ul></div>
  </article>`).join("");
 bindExpandButtons($("discussionList"));
 activeQuestions=currentTopic.questions[selectedAge==="primary"?"primary":"older"];
 questionIndex=0;
 renderQuestion();
 $("challengeTitle").textContent=currentTopic.challenge.title;
 $("challengeText").textContent=currentTopic.challenge.text;
 $("challengeTask").textContent=currentTopic.challenge.task;
 $("challengeHint").textContent=currentTopic.challenge.hint;
 $("challengeHint").classList.add("hidden");
 showScreen("story");
}
function renderQuestion(){
 chosenAnswer=null; questionResolved=false;
 const q=activeQuestions[questionIndex];
 $("questionText").textContent=q.text;
 $("questionCountLabel").textContent=`السؤال ${String(questionIndex+1).padStart(2,"0")} من ${activeQuestions.length}`;
 $("questionHelper").innerHTML=`<button class="presenter-expand" type="button" data-expand="questionPresenterNotes" aria-expanded="false" aria-label="إظهار نقاط الإجابة">＋</button><span class="question-helper-label">نقاط الإجابة والتوضيح للمُقدِّمة</span>${expandableNotes(q.notes,"الإجابة والتفسير","questionPresenterNotes")}`;
 bindExpandButtons($("questionHelper"));
 $("answers").innerHTML="";
 q.answers.forEach((answer,index)=>{
  const b=document.createElement("button");
  b.className="answer-option"; b.textContent=answer;
  b.addEventListener("click",()=>{
   if(questionResolved)return;
   chosenAnswer=index;
   document.querySelectorAll("#answers .answer-option").forEach(x=>x.classList.remove("selected"));
   b.classList.add("selected"); $("confirmAnswerBtn").disabled=false;
  });
  $("answers").appendChild(b);
 });
 $("answerFeedback").textContent=""; $("answerFeedback").className="answer-feedback";
 $("confirmAnswerBtn").disabled=true; $("toChallengeBtn").disabled=true;
 $("toChallengeBtn").textContent=questionIndex===activeQuestions.length-1?"الانتقال إلى تحدي الفريق ←":"السؤال التالي ←";
}
function revealAnswer(){
 const q=activeQuestions[questionIndex], correct=q.correct;
 document.querySelectorAll("#answers .answer-option").forEach((b,i)=>{b.disabled=true;if(i===correct)b.classList.add("correct")});
 $("answerFeedback").textContent="الإجابة الصحيحة: "+q.answers[correct]+". "+q.explain;
 $("answerFeedback").className="answer-feedback good";
 questionResolved=true; $("confirmAnswerBtn").disabled=true; $("toChallengeBtn").disabled=false;
}
function celebrateCorrectAnswer(){
 const layer=$("celebration");
 const pieces=Array.from({length:42},(_,i)=>`<i style="left:${(i*37)%100}%;animation-delay:${((i*13)%35)/100}s"></i>`).join("");
 layer.innerHTML=`<div class="confetti-rain">${pieces}</div><div class="confetti-message">إجابة صحيحة! أحسنتم<div class="confetti-pieces">✦　✧　✦　✧　✦</div></div>`;
 layer.classList.remove("hidden"); layer.classList.add("celebrate-now");
 setTimeout(()=>{layer.classList.add("hidden");layer.classList.remove("celebrate-now");},1900);
}
function playLocalSound(id){
 const audio=$(id); if(!audio)return;
 try{audio.pause();audio.currentTime=0;audio.volume=0.8;const p=audio.play();if(p&&p.catch)p.catch(()=>{});}catch(e){}
}
function confirmAnswer(){
 if(chosenAnswer===null||questionResolved)return;
 const q=activeQuestions[questionIndex];
 if(chosenAnswer===q.correct){
  $("answerFeedback").textContent="إجابة صحيحة! تفكير ممتاز. "+q.explain;
  $("answerFeedback").className="answer-feedback good";
  $("answers").children[chosenAnswer].classList.add("correct");
  celebrateCorrectAnswer(); playLocalSound("successAudio");
  questionResolved=true;
  document.querySelectorAll("#answers .answer-option").forEach(b=>b.disabled=true);
  $("confirmAnswerBtn").disabled=true; $("toChallengeBtn").disabled=false;
 }else{
  $("answerFeedback").textContent="مش الاختيار الصحيح، ودي فرصة نتعلم. هنراجع الإجابة الصحيحة مع بعض.";
  $("answerFeedback").className="answer-feedback bad";
  $("answers").children[chosenAnswer].classList.add("wrong");
  playLocalSound("wrongAudio");
  questionResolved=true;
  document.querySelectorAll("#answers .answer-option").forEach(b=>b.disabled=true);
  $("confirmAnswerBtn").disabled=true;
  setTimeout(revealAnswer,850);
 }
}
function nextQuestion(){
 if(!questionResolved)return;
 if(questionIndex<activeQuestions.length-1){questionIndex++;renderQuestion();}
 else showScreen("challenge");
}
function showClosing(){
 $("takeaways").innerHTML="<ul>"+currentTopic.takeaways.map(x=>`<li>${x}</li>`).join("")+"</ul>";
 $("closingPhrase").textContent=currentTopic.closing;
 $("endSessionBtn").textContent=(completedTopics.size+(completedTopics.has(currentTopic.id)?0:1)===topics.length)?"الانتقال إلى التحدي الفردي":"حفظ التقدم والعودة للموضوعات";
 showScreen("closing");
}
$("startBtn").addEventListener("click",()=>showScreen("age"));
document.querySelectorAll("[data-age]").forEach(b=>b.addEventListener("click",()=>{selectedAge=b.dataset.age;renderTopics();showScreen("topics")}));
$("beginTopicBtn").addEventListener("click",startStory);
document.querySelectorAll("[data-next]").forEach(b=>b.addEventListener("click",()=>{if(b.dataset.next==="closing")showClosing();else showScreen(b.dataset.next)}));
document.querySelectorAll("[data-back]").forEach(b=>b.addEventListener("click",()=>showScreen(b.dataset.back)));
$("confirmAnswerBtn").addEventListener("click",confirmAnswer);
$("revealAnswerBtn").addEventListener("click",revealAnswer);
$("toChallengeBtn").addEventListener("click",nextQuestion);
$("showHintBtn").addEventListener("click",()=>$("challengeHint").classList.toggle("hidden"));
$("backToTopicsBtn").addEventListener("click",()=>{renderTopics();showScreen("topics");});
$("endSessionBtn").addEventListener("click",()=>{
 completedTopics.add(currentTopic.id);
 if(completedTopics.size===topics.length) showScreen("individual");
 else { renderTopics(); showScreen("topics"); }
});
document.querySelectorAll("#individualAnswers .answer-option").forEach(b=>b.addEventListener("click",()=>{
 document.querySelectorAll("#individualAnswers .answer-option").forEach(x=>x.classList.remove("selected"));
 b.classList.add("selected");
 $("individualFeedback").textContent=b.dataset.correct==="true"?"إجابة صحيحة! التأكد قبل المشاركة تصرف واعي.":"فكّر مرة تانية: هل نعرف مصدر المحتوى ومين ممكن يشوفه؟";
 $("individualFeedback").className="answer-feedback "+(b.dataset.correct==="true"?"good":"bad");
}));
$("finishBtn").addEventListener("click",()=>showScreen("finish"));
$("restartBtn").addEventListener("click",()=>{completedTopics.clear();renderTopics();showScreen("home")});
$("brandHome").addEventListener("click",e=>{e.preventDefault();showScreen("home")});
renderTopics();
